 393	\begin{lemma}[Recovery of the components of a combined polynomial]
 394		\label{lem:ld-combining-split}
 395		\lean{MIPStarRE.QPBT.splitCombinedPoly}
 396		\lean{MIPStarRE.QPBT.splitCombinedPoly_combinePolyTuple}
 397		\lean{MIPStarRE.QPBT.combinePolyTuple_injective}
 398		\lean{MIPStarRE.QPBT.IsDirectCombined, MIPStarRE.QPBT.directTupleOfCombined}
 399		\lean{MIPStarRE.QPBT.directTupleOfCombined_directCombinedPolynomial}
 400		\leanok
 401		\uses{def:ld-combining-map}
 402		Let $\mathrm{split}_r$ denote the substitution of the $r$-th standard basis
 403		vector of $\F_q^k$ for the combining coordinates, a ring homomorphism
 404		$\F_q[u,\alpha] \to \F_q[u]$ fixing the point coordinates.  Then
 405		$\mathrm{split}_r(\mathrm{comb}_g) = g_r$ for every tuple $g$ and every
 406		$r$.  Consequently $g \mapsto \mathrm{comb}_g$ is injective, and the map
 407		sending $p \in \polyfunc{m+k}{q}{d}$ to the unique tuple $g$ with
 408		$\mathrm{comb}_g = p$ when $p$ is of that form, and to the zero tuple
 409		otherwise, is a well-defined total map $\mathrm{split}$ with
 410		$\mathrm{split}(\mathrm{comb}_g) = g$.
 411	\end{lemma}
 412	\begin{proof}
 413		\leanok
 414		\uses{def:ld-combining-map}
 415		Applying the homomorphism $\mathrm{split}_r$ to the sum defining
 416		$\mathrm{comb}_g$ sends the summand of index $s$ to $g_s$ when $s = r$ and to
 417		$0$ otherwise, since the combining coordinate carrying $\alpha_s$ is sent to
 418		$1$ for $s = r$ and to $0$ otherwise, while $g_s$, which involves no
 419		combining coordinate, is fixed; the sum is therefore $g_r$.
 420		Injectivity follows, and it makes the case distinction defining
 421		$\mathrm{split}$ unambiguous.  The value on polynomials that are not
 422		combined is immaterial: the source leaves it arbitrary, and the estimates
 423		below use only the value on combined polynomials.
 424	\end{proof}
