 426	\begin{lemma}[Collision of two linear forms in the combining variables]
 427		\label{lem:ld-combining-collision}
 428		\lean{MIPStarRE.QPBT.combiningLinearForm}
 429		\lean{MIPStarRE.QPBT.combiningLinearForm_injective}
 430		\lean{MIPStarRE.QPBT.combiningLinearForm_agreementProbability_le}
 431		\lean{MIPStarRE.QPBT.directCombiningCollision_avg_le}
 432		\leanok
 433		\uses{lem:schwartz-zippel-total-degree}
 434		Let $c, b \in \F_q^k$ with $c \neq b$.  Then
 435		\[
 436			\Pr_{\alpha \in \F_q^k}\Bigl[\; \sum_{r} c_r \alpha_r
 437				= \sum_{r} b_r \alpha_r \;\Bigr] \;\le\; \frac1q\;,
 438		\]
 439		the probability being over a uniformly random $\alpha$.
 440	\end{lemma}
 441	\begin{proof}
 442		\leanok
 443		\uses{lem:schwartz-zippel-total-degree}
 444		The two sides are the evaluations at $\alpha$ of the linear forms
 445		$\sum_r c_r X_r$ and $\sum_r b_r X_r$ in $k$ variables.  The coefficient of
 446		$X_r$ in such a form is $c_r$, so the two forms are distinct polynomials,
 447		and each has total degree at most $1$.  Lemma~\ref{lem:schwartz-zippel-total-degree}
 448		bounds the probability that two distinct polynomials of total degree at most
 449		$1$ agree at a uniformly random point of $\F_q^k$ by $1/q$.
 450	\end{proof}
