1582	\section{Canonical parameters of the Pauli basis test}
1583	% Paper label sec:qld-complexity kept for cross-reference fidelity (the complexity
1584	% statements of that subsection are outside the scope of this development).
1585	\label{sec:qld-complexity}
1586	
1587	We specify a canonical setting of the parameter tuple $\mathsf{qldparams}$ as a function of an integer $R$, and bound the resulting soundness function. Here $\log$ denotes the base-two logarithm, and $\ln$ denotes the natural logarithm.
1588	
1589	\begin{definition}[Canonical parameters of the Pauli basis test]\label{def:introparams}
1590		\lean{MIPStarRE.QPBT.introParamsC, MIPStarRE.QPBT.introParamsTuple, MIPStarRE.QPBT.AdmissibleParams.ofTuple, MIPStarRE.QPBT.introParams}
1591		\leanok
1592		\uses{thm:pauli}
1593		Let $a, b$ be the universal constants of Theorem~\ref{thm:pauli}, and let $c$ be the smallest \emph{even} integer that is at least $(b+a)/b$. For every integer $R \ge 4$, define the tuple $\mathsf{introparams}(R) = (q, m, d)$ by
1594		\begin{itemize}
1595			\item $q = 2^k$ for $k = c \lceil \log \log R \rceil + 1$,
1596			\item $m = 2^j$, where $j$ is the unique integer with $2^j \le c \lceil \log R \rceil + 1 < 2^{j+1}$,
1597			\item $d = 1$.
1598		\end{itemize}
1599		The letter $k$ here denotes the exponent of the field size and is unrelated to the simultaneity parameter $k$ of the classical game. With this choice the Pauli basis test certifies the presence of an $M = 2^m$-qudit maximally entangled state of local dimension $q$, equivalently an $(M \log q)$-qubit EPR state, and the choice $d = 1$ runs the low individual degree test multilinearly.
1600	\end{definition}
1601	
1602	\begin{lemma}[Soundness bound for the canonical parameters]\label{lem:delta-bound}
1603		\lean{MIPStarRE.QPBT.introParamsTuple_isAdmissible, MIPStarRE.QPBT.le_two_pow_introParams_m, MIPStarRE.QPBT.exists_deltaQld_introParams_bound}
1604		\leanok
1605		\uses{def:introparams, def:admissible, thm:pauli}
1606		For all integers $R \ge 4$, the parameter tuple $\mathsf{introparams}(R) = (q,m,d)$ is admissible (Definition~\ref{def:admissible}) and satisfies $2^m \ge R$. Furthermore, there exist universal constants $a' \ge 1$ and $0 < b' \le 1$ such that, for every $\eps \ge 0$, the function $\delta_{\mathrm{qld}}(\eps, m, d, q)$ of Theorem~\ref{thm:pauli} is at most
1607		\[
1608			a' \bigl( (\log R)^{a'} \cdot \eps^{b'} + (\log R)^{-b'} \bigr)\;.
1609		\]
1610	\end{lemma}
1611	\begin{proof}
1612		\leanok
1613		\uses{def:introparams, def:admissible, def:admissible-size, thm:pauli, lem:delta-bound-envelope-support}
1614		Since $c$ is even, the exponent $k = c \lceil \log\log R \rceil + 1$ is odd, so $q = 2^k$ is an admissible field size; $m$ divides $q$ because $2^j \le c \lceil \log R \rceil + 1 \le 2 \log^c R \le 2^k$, so $j \le k$ and both are powers of $2$; and $d = 1 \ge 1$. Hence the tuple is admissible. Since $m = 2^j \ge (c/2) \log R$, we get $2^m \ge R^{c/2} \ge R$, using $c \ge 2$.
1615	
1616		For the soundness bound, write $\delta_{\mathrm{qld}}(\eps,m,d,q) = a(md)^a \eps^b + a(md)^a q^{-b} + a(md)^a 2^{-bmd}$ and use $d = 1$, $\log R \le m \le 2c \log R$, and $q = 2^k \ge \log^c R$. Set
1617		\[
1618			C = \frac{\lceil a + b \rceil !}{(b \ln 2)^{\lceil a + b \rceil}}
1619			\qquad \text{and} \qquad
1620			a' = a\bigl( (2c)^a + C \bigr)\;,
1621		\]
1622		both depending only on the universal constants $a$ and $b$; since $a \ge 1$, $c \ge 2$ and $C \ge 0$, one has $a' \ge a \ge 1$. The first term is at most $a(2c)^a (\log R)^a \eps^b \le a' (\log R)^{a'} \eps^b$, using $\log R \ge 2 \ge 1$ and $a \le a'$. The second term is at most $a(2c)^a (\log R)^{a - cb} \le a(2c)^a (\log R)^{-b}$, since $cb - a \ge b$ by the choice of $c$. For the third term, split $m^a = m^{a+b} \cdot m^{-b}$ and bound the first factor against the exponential: for all real $s$, all $t > 0$ and all $x \ge 1$, the Taylor estimate $y^n / n! \le e^y$ of the exponential, taken at $y = (t \ln 2) x$ and $n = \lceil s \rceil_{+} = \max(\lceil s \rceil, 0)$, gives
1623		\[
1624			x^s\, 2^{-tx} \le \frac{\lceil s \rceil_{+}!}{(t \ln 2)^{\lceil s \rceil_{+}}}\;.
1625		\]
1626		With $s = a + b$, $t = b$ and $x = m$ the right-hand side is the constant $C$ above, so
1627		\[
1628			a(md)^a\, 2^{-bm}
1629			= a \bigl( m^{a+b}\, 2^{-bm} \bigr) m^{-b}
1630			\le a\, C\, m^{-b}
1631			\le a\, C\, (\log R)^{-b}\;,
1632		\]
1633		the last step using $m \ge \log R \ge 1$. Summing the three bounds, the statement follows with $a'$ as above and $b' = b$.
1634	\end{proof}
1635	
1636	\begin{lemma}[Formalization support for Lemma~\ref{lem:delta-bound}]
1637	\label{lem:delta-bound-envelope-support}
1638	\lean{MIPStarRE.LDT.rpow_mul_two_rpow_neg_le}
1639	\leanok
1640	For real $s$, $t > 0$ and $x \ge 1$, writing $\lceil s \rceil_{+} = \max(\lceil s \rceil, 0)$,
1641	\[
1642	  x^{s}\, 2^{-t x} \le \frac{\lceil s \rceil_{+}!}{(t \ln 2)^{\lceil s \rceil_{+}}} .
1643	\]
1644	This is the explicit envelope used for the third term in the proof of Lemma~\ref{lem:delta-bound}, with $x = m$, $s = a + b$ and $t = b$.
1645	\end{lemma}
1646	\begin{proof}
1647	\leanok
1648	Since $x \ge 1$, $x^{s} \le x^{\lceil s \rceil_{+}}$, and the Taylor lower bound $y^{n}/n! \le e^{y}$ at $y = t x \ln 2$ and $n = \lceil s \rceil_{+}$ gives $x^{n} (t \ln 2)^{n} \le n!\, 2^{t x}$.
1649	\end{proof}
1650	
1651	\begin{remark}[A comparison of exponents in the source proof of Lemma~\ref{lem:delta-bound}]\label{rem:delta-bound-exponent-comparison}
1652		The source proof bounds the third term of $\delta_{\mathrm{qld}}$ by asserting $2^{-bmd} \le q^{-b}$ ``because $k \le m$'', comparing the field exponent $k = c \lceil \log\log R \rceil + 1$ with $m = 2^j$. The inequality $k \le m$ does not follow from Definition~\ref{def:introparams}: if the universal constants of Theorem~\ref{thm:pauli} were $a = 1$ and $b = 1/2$, then $c = 4$, and $R = 5$ gives $k = 9$ and $m = 8$. The proof above instead bounds the third term directly, comparing $m^{a+b} 2^{-bm}$ with an explicit constant and using only $m \ge (c/2) \log R \ge \log R$, which yields the same conclusion after enlarging the universal constant $a'$.  The comparison and correction are documented in \cite{gap:qpbt_delta-bound-exponent-comparison}.
1653	\end{remark}
